package io.xeros.solo;
import io.xeros.*;import io.xeros.model.entity.npc.*;import io.xeros.model.definitions.*;import java.util.*;
public class BossWorld69Dump{public static void main(String[]args)throws Exception{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();String[] names={"snake","kratos","tarn","callisto","chaos","archaeologist","scorpia","seren","venenatis","vet'ion","barrelchest","hunllef","gorilla","shaman"};for(NPC n:NPCHandler.npcs)if(n!=null&&Arrays.stream(names).anyMatch(v->n.getName().toLowerCase().contains(v)))System.out.println("WORLD "+n.getNpcId()+" "+n.getName()+" "+n.getX()+","+n.getY()+","+n.getHeight()+" HP="+n.getHealth().getMaximumHealth()+" "+n.getClass().getSimpleName());System.out.println("BOSS_WORLD69_DUMP_PASS");System.exit(0);}}
